<template><section class="mx-auto max-w-3xl px-4 py-10 sm:px-6"><div class="glass-card rounded-[2rem] p-7"><p class="text-sm uppercase tracking-[.3em] text-amber-200">DOKU Payment Status</p><h1 class="mt-3 text-4xl font-bold">{{ heading }}</h1><p class="mt-3 text-slate-300">{{ description }}</p><div class="mt-7 rounded-2xl border border-white/10 bg-white/5 p-5"><p class="text-xs uppercase tracking-widest text-slate-400">Payment status</p><p class="mt-2 text-2xl font-bold" :class="statusClass">{{ statusLabel }}</p><p v-if="payment" class="mt-2 text-sm text-slate-400">Provider: {{ payment.provider }} · Amount: {{ currency(payment.gross_amount,payment.currency) }}</p><p v-if="polling" class="mt-3 text-sm text-amber-200">Checking for DOKU confirmation…</p></div><div class="mt-6 flex flex-wrap gap-3"><NuxtLink v-if="status==='success'" :to="`/dashboard/invoice?registration_id=${registrationId}`" class="rounded-full bg-amber-300 px-5 py-3 font-semibold text-slate-950">View invoice</NuxtLink><NuxtLink v-else-if="terminal" to="/dashboard/payment" class="rounded-full bg-amber-300 px-5 py-3 font-semibold text-slate-950">Try payment again</NuxtLink><button v-else class="rounded-full border border-white/20 px-5 py-3" :disabled="checking" @click="checkStatus">Check again</button><NuxtLink to="/dashboard" class="rounded-full border border-white/20 px-5 py-3">Dashboard</NuxtLink></div><div v-if="errorMessage" class="mt-5 rounded-2xl border border-red-400/30 bg-red-950/30 p-4 text-red-100"><p>{{ errorMessage }}</p><p v-if="requestId" class="mt-2 text-xs">Reference: {{ requestId }}</p></div></div></section></template>
<script setup lang="ts">
import {usePayment,type PaymentItem} from '~/composables/usePayment';definePageMeta({middleware:'auth'});useSeoMeta({title:'Payment Status | IWBIF 2026'});const route=useRoute();const {getPayment,getInvoiceByRegistration}=usePayment();const STORAGE_REGISTRATION='iwbif-doku-registration-id';const STORAGE_PAYMENT='iwbif-doku-payment-id';const paymentId=ref('');const registrationId=ref('');const payment=ref<PaymentItem|null>(null);const status=ref('pending');const polling=ref(false);const checking=ref(false);const errorMessage=ref('');const requestId=ref('');let timer:ReturnType<typeof setInterval>|null=null;let attempts=0;const maxAttempts=30;const terminal=computed(()=>['failed','expired'].includes(status.value));const statusLabel=computed(()=>({created:'Created',pending:'Awaiting verification',success:'Payment successful',failed:'Payment failed',expired:'Checkout expired'}[status.value]||status.value));const heading=computed(()=>status.value==='success'?'Payment received':terminal.value?'Payment not completed':'Payment processing');const description=computed(()=>status.value==='success'?'DOKU notification has been verified by the backend. Registration confirmation remains a separate organizer step.':terminal.value?'You may safely create a new DOKU Checkout.':'Do not create another checkout while verification is in progress.');const statusClass=computed(()=>status.value==='success'?'text-emerald-300':terminal.value?'text-red-300':'text-amber-200');const stop=()=>{if(timer)clearInterval(timer);timer=null;polling.value=false};const apiError=(error:unknown)=>{const value=error as {data?:{message?:string;request_id?:string}};requestId.value=value.data?.request_id||'';return value.data?.message||(error instanceof Error?error.message:'Payment status could not be retrieved.')};
const checkStatus=async()=>{if(checking.value)return;checking.value=true;errorMessage.value='';try{if(paymentId.value){const response=await getPayment(paymentId.value);payment.value=response.data;status.value=response.data.transaction_status}else if(registrationId.value){const response=await getInvoiceByRegistration(registrationId.value);payment.value=response.data.payment;status.value=response.data.payment.transaction_status}else{throw new Error('Payment reference was not found in this browser.')}if(status.value==='success'||terminal.value)stop()}catch(error){errorMessage.value=apiError(error)}finally{checking.value=false}};
onMounted(async()=>{const queryPayment=Array.isArray(route.query.payment_id)?route.query.payment_id[0]:route.query.payment_id;const queryRegistration=Array.isArray(route.query.registration_id)?route.query.registration_id[0]:route.query.registration_id;paymentId.value=(typeof queryPayment==='string'?queryPayment:'')||sessionStorage.getItem(STORAGE_PAYMENT)||'';registrationId.value=(typeof queryRegistration==='string'?queryRegistration:'')||sessionStorage.getItem(STORAGE_REGISTRATION)||'';await checkStatus();if(status.value==='created'||status.value==='pending'){polling.value=true;timer=setInterval(async()=>{attempts++;await checkStatus();if(attempts>=maxAttempts)stop()},4000)}});onBeforeUnmount(stop);const currency=(amount:number,code:string)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:code||'IDR',maximumFractionDigits:0}).format(amount);
</script>
